import {redisCommand} from "./redis-protocol";type Entry={value:unknown;expiresAt:number};const memory=new Map<string,Entry>();
export function redisConfigured(){return Boolean(process.env.REDIS_URL||(process.env.UPSTASH_REDIS_REST_URL&&process.env.UPSTASH_REDIS_REST_TOKEN));}
export async function cacheCommand(command:unknown[]){if(process.env.REDIS_URL)return redisCommand(command);if(!process.env.UPSTASH_REDIS_REST_URL||!process.env.UPSTASH_REDIS_REST_TOKEN)throw new Error("redis_not_configured");const response=await fetch(process.env.UPSTASH_REDIS_REST_URL,{method:"POST",headers:{Authorization:`Bearer ${process.env.UPSTASH_REDIS_REST_TOKEN}`,"Content-Type":"application/json"},body:JSON.stringify(command),cache:"no-store"});if(!response.ok)throw new Error("redis_request_failed");const body=await response.json() as {result?:unknown};return body.result;}
export async function cacheGet<T>(key:string):Promise<T|null>{if(redisConfigured()){const value=await cacheCommand(["GET",key]);return typeof value==="string"?JSON.parse(value) as T:null;}if(process.env.NODE_ENV==="production")return null;const entry=memory.get(key);if(!entry||entry.expiresAt<Date.now()){memory.delete(key);return null;}return entry.value as T;}
export async function cacheSet(key:string,value:unknown,ttlSeconds=60){if(redisConfigured()){await cacheCommand(["SET",key,JSON.stringify(value),"EX",ttlSeconds]);return;}if(process.env.NODE_ENV!=="production")memory.set(key,{value,expiresAt:Date.now()+ttlSeconds*1000});}
export async function cacheDeletePattern(prefix:string){if(redisConfigured()){let cursor="0";do{const result=await cacheCommand(["SCAN",cursor,"MATCH",`${prefix}*`,"COUNT","100"]);if(!Array.isArray(result))break;cursor=String(result[0]);const keys=Array.isArray(result[1])?result[1]:[];if(keys.length)await cacheCommand(["DEL",...keys]);}while(cursor!=="0");return;}for(const key of memory.keys())if(key.startsWith(prefix))memory.delete(key);}
export function cacheStatus(){return redisConfigured()?"redis":process.env.NODE_ENV==="production"?"disabled":"memory";}
